package com.lqq.supportflow.knowledge.application;
import com.lqq.supportflow.knowledge.domain.*; import com.lqq.supportflow.model.ModelEmbeddingService; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class IndexKnowledgeDocumentService { private final KnowledgeDocumentPort documents; private final KnowledgeChunkPort chunks; private final ModelEmbeddingService embeddings; private final KnowledgeSearchIndex index; public IndexKnowledgeDocumentService(KnowledgeDocumentPort documents,KnowledgeChunkPort chunks,ModelEmbeddingService embeddings,KnowledgeSearchIndex index){this.documents=documents;this.chunks=chunks;this.embeddings=embeddings;this.index=index;} @Transactional public KnowledgeDocument index(Long tenantId,Long knowledgeBaseId,Long documentId){KnowledgeDocument document=documents.findById(tenantId,knowledgeBaseId,documentId).orElseThrow(()->new IllegalArgumentException("document does not belong to tenant"));if(document.status()!=IngestionStatus.EMBEDDING)throw new IllegalArgumentException("document is not ready for embedding");List<KnowledgeChunk> documentChunks=chunks.findByDocument(tenantId,knowledgeBaseId,documentId);if(documentChunks.isEmpty())throw new IllegalArgumentException("document has no chunks");List<float[]> vectors=embeddings.embed(tenantId,documentChunks.stream().map(KnowledgeChunk::content).toList());KnowledgeDocument indexing=documents.transitionStatus(tenantId,documentId,IngestionStatus.EMBEDDING,IngestionStatus.INDEXING);List<IndexedKnowledgeChunk> entries=new ArrayList<>();for(int position=0;position<documentChunks.size();position++)entries.add(new IndexedKnowledgeChunk(documentChunks.get(position),vectors.get(position)));index.index(tenantId,knowledgeBaseId,documentId,entries);return documents.transitionStatus(tenantId,indexing.id(),IngestionStatus.INDEXING,IngestionStatus.INDEXED);}}
